    for r in range(h):
        for c in range(w):
            if grid[r][c] != 6 or (r, c) in seen:
                continue

            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and
                            grid[yy][xx] == 6 and (yy, xx) not in seen):
                        seen.add((yy, xx))
                        stack.append((yy, xx))

            r0 = min(y for y, x in cells)
            r1 = max(y for y, x in cells)
            c0 = min(x for y, x in cells)
            c1 = max(x for y, x in cells)
            patch = set(cells)
            ph, pw = r1 - r0 + 1, c1 - c0 + 1

            best = None
            # Search for a matching surrounding pattern elsewhere in the grid.
            for flip_y, flip_x in ((0, 0), (1, 0), (0, 1), (1, 1)):
                for sy in range(h - ph + 1):
                    for sx in range(w - pw + 1):
                        if sy == r0 and sx == c0 and not flip_y and not flip_x:
                            continue
                        score = matches = 0
                        for yy in range(max(0, r0 - 4), min(h, r1 + 5)):
                            for xx in range(max(0, c0 - 4), min(w, c1 + 5)):
