                                    continue
                                dy, dx = yy - r0, xx - c0
                                if flip_y:
                                    dy = ph - 1 - dy
                                if flip_x:
                                    dx = pw - 1 - dx
                                ty, tx = sy + dy, sx + dx
                                if 0 <= ty < h and 0 <= tx < w and grid[ty][tx] != 6:
                                    matches += 1
                                    score += 2 if grid[yy][xx] == grid[ty][tx] else -1
