    out = [row[:] for row in grid]
    side = 32

    def symmetries(r, c):
        return [
            (r, side - 1 - c),
            (side - 1 - r, c),
            (side - 1 - r, side - 1 - c),
            (c, r),
            (c, side - 1 - r),
            (side - 1 - c, r),
            (side - 1 - c, side - 1 - r),
        ]

    for r in range(n):
        for c in range(m):
            if grid[r][c] != 6:
                continue
            vals = []
            for rr, cc in symmetries(r, c):
                if 0 <= rr < n and 0 <= cc < m and grid[rr][cc] != 6:
                    vals.append(grid[rr][cc])
            if vals:
                out[r][c] = max(set(vals), key=vals.count)
    return out
